        input: String,
    },
    Edit {
        task_id: usize,
        command: Option<String>,
        path: Option<String>,
        label: Option<String>,
    },
    Group(GroupMessage),
    Parallel {
        parallel_tasks: usize,
        group: String,
    },
    Clean {
        finished_only: bool,
