use serde::{Deserialize, Serialize};
use std::path::PathBuf;

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct Settings {
    pub client: ClientSettings,
    pub daemon: DaemonSettings,
    pub shared: SharedSettings,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct ClientSettings {
    pub restart_in_place: bool,
    pub read_local_logs: bool,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct DaemonSettings {
    pub pause_on_error: bool,
    pub callback: Option<String>,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct SharedSettings {
    pub socket_path: PathBuf,
    pub secret_path: PathBuf,
}

impl Settings {
    pub fn new() -> anyhow::Result<Self> {
        let home = std::env::var("HOME")?;
        let config_path = format!("{}/.config/pueue/pueue.yml", home);
        // In a real implementation we would load from file.
        // For now let's use defaults that match what we observed.
        Ok(Settings {
            client: ClientSettings {
                restart_in_place: false,
                read_local_logs: true,
            },
            daemon: DaemonSettings {
                pause_on_error: false,
                callback: None,
            },
            shared: SharedSettings {
                socket_path: PathBuf::from(format!("{}/.local/share/pueue/pueue_agent.socket", home)),
                secret_path: PathBuf::from(format!("{}/.local/share/pueue/shared_secret", home)),
            },
        })
    }
}
EOF
"}

