{"command":"cat <<'EOF' > src/main.rs
use clap::{Parser, Subcommand, ValueEnum};
use pueue::message::{Message, TaskSelection, GroupMessage};
use pueue::settings::Settings;
use std::io::{Read, Write};
use std::os::unix::net::UnixStream;
use byteorder::{BigEndian, WriteBytesExt, ReadBytesExt};

#[derive(Parser)]
#[command(name = "pueue", version = "4.0.4", about = "Interact with the Pueue daemon", long_about = "Use the --help long form to get detailed help output on each subcommand!")]
struct Cli {
    #[arg(short, long, action = clap::ArgAction::Count, help = "Verbose mode (-v, -vv, -vvv)")]
    verbose: u8,

    #[arg(long, default_value = "auto", help = "Colorize the output; auto enables color output when connected to a tty")]
    color: String,

    #[arg(short, long, help = "If provided, Pueue only uses this config file.\n\nThis path can also be set via the \"PUEUE_CONFIG_PATH\" environment variable. The commandline option overwrites the environment variable!")]
    config: Option<std::path::PathBuf>,

    #[arg(short, long, help = "The name of the profile that should be loaded from your config file")]
    profile: Option<String>,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    #[command(about = "Enqueue a task for execution")]
    Add {
        #[arg(help = "The command to be added", required = true)]
        command: Vec<String>,
        #[arg(short, long, help = "Specify current working directory")]
        working_directory: Option<String>,
        #[arg(short, long, help = "Escape any special shell characters (\" \", \"&\", \"!\", etc.).\nBeware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\").")]
        escape: bool,
        #[arg(short, long, help = "Immediately start the task")]
        immediate: bool,
        #[arg(long, help = "Immediately follow a task, if it's started with --immediate")]
        follow: bool,
        #[arg(short, long, help = "Create the task in Stashed state.\n\nUseful to avoid immediate execution if the queue is empty.")]
        stashed: bool,
        #[arg(short, long, help = "Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted formats")]
        delay: Option<String>,
        #[arg(short, long, help = "Assign the task to a group.\n\nGroups kind of act as separate queues. All groups run in parallel and you can specify the amount of parallel tasks for each group. If no group is specified, the default group will be used.\n\nCreate groups via the `pueue group` subcommand")]
        group: Option<String>,
        #[arg(short, long, help = "Start the task once all specified tasks have successfully finished.\n\nAs soon as one of the dependencies fails, this task will fail as well.")]
        after: Vec<usize>,
        #[arg(short, long, help = "Start this task with a higher priority.\n\nThe higher the number, the faster it will be processed.")]
        priority: Option<i32>,
        #[arg(short, long, help = "Add some information for yourself.\n\nThis string will be shown in the \"status\" table. There's no additional logic connected to it.")]
        label: Option<String>,
        #[arg(short, long, help = "Only return the task id instead of a text.\n\nThis is useful when working with dependencies in scripts.")]
        print_task_id: bool,
    },
    #[command(about = "Display the current status of all tasks")]
    Status {
        #[arg(help = "Users can specify a custom query to filter for specific values, order by a column or limit the amount of tasks listed.")]
        query: Vec<String>,
        #[arg(short, long, help = "Print the current state as json to stdout. This does not include the output of tasks. Use log -j if you want everything")]
        json: bool,
        #[arg(short, long, help = "Only show tasks of a specific group")]
        group: Option<String>,
    },
    #[command(about = "Either pause running tasks or specific groups of tasks")]
    Pause {
        #[arg(help = "The task ids to be paused")]
        task_ids: Vec<usize>,
        #[arg(short, long, help = "Pause a specific group")]
        group: Option<String>,
        #[arg(short, long, help = "Pause all groups and tasks")]
        all: bool,
        #[arg(short, long, help = "Wait for the tasks to finish instead of pausing them immediately")]
        wait: bool,
    },
    // ... I'll add more if needed
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();
    let settings = Settings::new()?;

    // Handle default command (status)
    let command = cli.command.unwrap_or(Commands::Status { query: vec![], json: false, group: None });

    let message = match command {
        Commands::Add { command, group, after, priority, label, print_task_id, immediate, .. } => {
            Message::Add {
                command: command.join(" "),
                path: std::env::current_dir()?.to_string_lossy().into_owned(),
                envs: std::collections::HashMap::new(),
                group: group.unwrap_or_else(|| "default".to_string()),
                enqueue_at: None,
                dependencies: after,
                priority,
                label,
                print_task_id,
                start_immediately: immediate,
            }
        }
        Commands::Status { .. } => Message::Status,
        Commands::Pause { task_ids, group, all, wait } => {
            let tasks = if all {
                TaskSelection::All
            } else if let Some(g) = group {
                TaskSelection::Group(g)
            } else {
                TaskSelection::TaskIds(task_ids)
            };
            Message::Pause { tasks, wait }
        }
        _ => todo!(),
    };

    // Connect to daemon
    let mut stream = UnixStream::connect(&settings.shared.socket_path)?;

    // Send secret
    let secret = std::fs::read(&settings.shared.secret_path)?;
    stream.write_u64::<BigEndian>(secret.len() as u64)?;
    stream.write_all(&secret)?;

    // Receive version (skip for now)
    let version_size = stream.read_u64::<BigEndian>()?;
    let mut version_buf = vec![0u8; version_size as usize];
    stream.read_exact(&mut version_buf)?;

    // Send message
    let encoded = serde_cbor::to_vec(&message)?;
    stream.write_u64::<BigEndian>(encoded.len() as u64)?;
    stream.write_all(&encoded)?;

    // Receive response (skip for now)
    Ok(())
}
EOF
"}

