    let settings = Settings::new()?;
    if settings.shared.socket_path.exists() {
        std::fs::remove_file(&settings.shared.socket_path)?;
    }
    let listener = UnixListener::bind(&settings.shared.socket_path)?;

    loop {
        let (mut stream, _) = listener.accept()?;

        // 1. Receive secret
        let secret_size = stream.read_u64::<BigEndian>()?;
        let mut secret = vec![0u8; secret_size as usize];
        stream.read_exact(&mut secret)?;

        // 2. Send version
        let version = serde_cbor::to_vec("4.0.4")?;
        stream.write_u64::<BigEndian>(version.len() as u64)?;
        stream.write_all(&version)?;

        // 3. Receive message
        let msg_size = stream.read_u64::<BigEndian>()?;
        let mut msg_buf = vec![0u8; msg_size as usize];
        stream.read_exact(&mut msg_buf)?;
        let _message: Message = serde_cbor::from_slice(&msg_buf)?;

        // (handle message)
    }
}
