    let mut version_buf = vec![0u8; version_size as usize];
    stream.read_exact(&mut version_buf)?;

    let encoded = serde_cbor::to_vec(&message)?;
    stream.write_u64::<BigEndian>(encoded.len() as u64)?;
    stream.write_all(&encoded)?;

    Ok(())
