        l = len(obj)
        res = b''
        if l <= 23:
            res = struct.pack("B", 0x80 + l)
        for item in obj:
            res += encode(item)
        return res
    if isinstance(obj, dict):
        l = len(obj)
        res = b''
        if l <= 23:
            res = struct.pack("B", 0xa0 + l)
        for k, v in obj.items():
            res += encode(k)
            res += encode(v)
        return res
    raise Exception(f"Unsupported type: {type(obj)}")

